      children: (0,jsx_runtime.jsx)(_components.code, {
        children: "function SARSA(env, gamma, alpha, epsilon, episodes) returns Q\n    Q(s, a) <- 0 for all s, a\n    for each episode do\n        s <- env.RESET()\n        a <- EPSILON-GREEDY(s, Q, epsilon)\n        while not TERMINAL(s) do\n            s', r <- env.STEP(a)\n            a' <- EPSILON-GREEDY(s', Q, epsilon)\n            Q(s, a) <- Q(s, a) + alpha[r + gamma Q(s', a') - Q(s, a)]\n            s <- s'; a <- a'\n    return Q\n"
      })
